class NodoReplica:
    def __init__(self, nombre):
        self.nombre = nombre
        self.valor = None

nodos = [NodoReplica("n1"), NodoReplica("n2"), NodoReplica("n3")]

def escribir_eventual(valor):
    # solo un nodo recibe la escritura de inmediato
    nodos[0].valor = valor

def leer_local(nodo):
    return nodo.valor

def leer_mayoria(valor_esperado):
    votos = sum(1 for n in nodos if n.valor == valor_esperado)
    return votos > len(nodos) / 2

def propagar():
    valor = nodos[0].valor
    for n in nodos[1:]:
        n.valor = valor

escribir_eventual("v1")
print(f"Lectura local en n2 justo despues de escribir: {leer_local(nodos[1])}")
print(f"Lectura por mayoria (aun no propagado): {leer_mayoria('v1')}")

propagar()
print(f"Lectura local en n2 tras propagar: {leer_local(nodos[1])}")
print(f"Lectura por mayoria (ya propagado): {leer_mayoria('v1')}")
